// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface RosterRangeOut {
  date_from: string;
  date_to: string;
  entries: RosterEntryOut[];
}

/** One rostered duty (service.ENTRY_COLS). A night shift belongs to the date it starts. */
export interface RosterEntryOut {
  roster_id: number;
  employee_id: number;
  emp_number: string;
  full_name: string;
  designation: string;
  staff_category: "Clinical" | "Nursing" | "Administrative" | "Technical" | "SupportZeroInterface" | "Visiting";
  roster_date: string;
  shift_pattern_id: number;
  shift_name: string;
  start_time: string;
  end_time: string;
  duty_area: "Ward" | "Department" | "Emergency" | "OT" | "Facility" | "Other";
  ward_id: number | null;
  ward_name: string | null;
  department_id: number | null;
  department_name: string | null;
  zone_label: string | null;
  is_on_call: boolean;
  notes: string | null;
  status: "Active" | "Cancelled";
  cancel_reason: string | null;
  /** Taken over from a colleague through this approved duty swap */
  swap_id: number | null;
  row_version: number;
  /** The beds of a ward duty (the nurse's "my beds") */
  bed_ids: number[];
}

/** Everything the planner grid needs for a range: shift patterns, public holidays and the staff I may roster. */
export interface RosterPlannerOut {
  date_from: string;
  date_to: string;
  shift_patterns: ShiftPatternOut[];
  holidays: HolidayBriefOut[];
  staff: RosterableStaffOut[];
}

export interface ShiftPatternOut {
  shift_pattern_id: number;
  name: string;
  start_time: string;
  /** Earlier than start_time for a night shift */
  end_time: string;
  grace_minutes: number;
  half_day_after_minutes: number;
  is_active: boolean;
  row_version: number;
}

export interface HolidayBriefOut {
  holiday_id: number;
  holiday_date: string;
  name: string;
}

export interface RosterableStaffOut {
  employee_id: number;
  emp_number: string;
  full_name: string;
  designation: string;
  staff_category: "Clinical" | "Nursing" | "Administrative" | "Technical" | "SupportZeroInterface" | "Visiting";
  department_id: number | null;
  department_name: string | null;
  /** A fixed default shift (null: works to the roster only) */
  default_shift_pattern_id: number | null;
  /** That default shift's weekly days off (ISO weekdays, 1 = Monday … 7 = Sunday); [] for roster-only staff */
  default_weekly_off_days: number[];
  /** Approved leave in the range (they cannot be rostered then) */
  leave: StaffLeaveOut[];
}

export interface StaffLeaveOut {
  employee_id: number;
  from_date: string;
  to_date: string;
  leave_type: "Annual" | "Casual" | "Sick" | "Maternity" | "Unpaid" | "Other";
}

export interface EntriesIn {
  entries: EntryIn[];
}

export interface EntryIn {
  employee_id: number;
  /** The date the shift STARTS (a night shift belongs to its start date) */
  roster_date: string;
  /** GET /rosters/staff → shift_patterns (HR: GET /hr/shift-patterns) */
  shift_pattern_id: number;
  duty_area?: "Ward" | "Department" | "Emergency" | "OT" | "Facility" | "Other";
  /** Required when duty_area is Ward */
  ward_id?: number | null;
  department_id?: number | null;
  zone_label?: string | null;
  /** Ward duties: the beds this nurse looks after */
  bed_ids?: number[];
  is_on_call?: boolean;
  notes?: string | null;
}

export interface EntryPatch {
  /** row_version you loaded (optimistic concurrency) */
  expected_version?: number | null;
  roster_date?: string | null;
  shift_pattern_id?: number | null;
  duty_area?: "Ward" | "Department" | "Emergency" | "OT" | "Facility" | "Other" | null;
  ward_id?: number | null;
  department_id?: number | null;
  zone_label?: string | null;
  bed_ids?: number[] | null;
  is_on_call?: boolean | null;
  notes?: string | null;
}

export interface RosterReasonIn {
  reason: string;
}

export interface CopyIn {
  source_from: string;
  source_to: string;
  /** Where the copy starts, e.g. next Monday */
  target_from: string;
  ward_id?: number | null;
  department_id?: number | null;
  staff_category?: "Clinical" | "Nursing" | "Administrative" | "Technical" | "SupportZeroInterface" | "Visiting" | null;
  /** Move everyone's pattern on by this many days within the period, wrapping round: 1 on a week makes each rest day move to the next weekday, so rest days (and Sunday duty) rotate week by week */
  rotate_days?: number;
}

export interface RosterCopyOut {
  created: RosterEntryOut[];
  skipped: CopySkippedOut[];
}

export interface CopySkippedOut {
  from_roster_id: number;
  employee_id: number;
  full_name: string;
  roster_date: string;
  /** The error code that stopped this entry (e.g. ROSTER_CONFLICT, LEAVE_CONFLICT) */
  reason: string;
}

export interface RosterWeekOut {
  week_start: string;
  week_end: string;
  /** Setting weekly_rest_days */
  rest_days_due: number;
  staff_without_rest_day: number;
  staff: WeekStaffOut[];
  days: WeekDayOut[];
}

/** One person's roster week. */
export interface WeekStaffOut {
  employee_id: number;
  emp_number: string;
  full_name: string;
  designation: string;
  staff_category: "Clinical" | "Nursing" | "Administrative" | "Technical" | "SupportZeroInterface" | "Visiting";
  department_name: string | null;
  /** On a fixed schedule (a default shift) during the week */
  has_default_shift: boolean;
  duty_dates: string[];
  /** Days without a duty and without leave */
  rest_dates: string[];
  leave_dates: string[];
  working_days: number;
  /** Duty days beyond the week's allowance (7 - rest_days_due), paid as extra duty */
  extra_duty_days: number;
  /** NoRestDay: fewer rest days than due; NotRostered: roster-only staff with no duty this week yet */
  status: "Ok" | "NoRestDay" | "NotRostered";
}

/** Staffing of one day of the week (with ward_id: that ward's duties). */
export interface WeekDayOut {
  day: string;
  /** ISO weekday, 1 = Monday … 7 = Sunday */
  weekday: number;
  holiday_name: string | null;
  on_duty: number;
  on_leave: number;
  resting: number;
  shifts: WeekShiftCountOut[];
}

export interface WeekShiftCountOut {
  shift_pattern_id: number;
  shift_name: string;
  start_time: string;
  end_time: string;
  staff: number;
}

/** A duty swap: a cover (one duty) or a swap (the requester works `return_duty` in exchange). */
export interface DutySwapOut {
  swap_id: number;
  kind: "Cover" | "Swap";
  status: "Requested" | "Accepted" | "Approved" | "Declined" | "Rejected" | "Cancelled" | "Expired";
  reason: string;
  roster_id: number;
  return_roster_id: number | null;
  requester_employee_id: number;
  requester_name: string;
  covering_employee_id: number;
  covering_name: string;
  staff_category: "Clinical" | "Nursing" | "Administrative" | "Technical" | "SupportZeroInterface" | "Visiting";
  /** The requester's duty the colleague is asked to work (as it was asked) */
  duty: RosterEntryOut;
  /** The colleague's duty the requester works in exchange */
  return_duty: RosterEntryOut | null;
  requested_at: string;
  responded_at: string | null;
  response_note: string | null;
  responded_by_name: string | null;
  decided_at: string | null;
  decision_note: string | null;
  /** The roster manager (null when no approval was needed) */
  decided_by_name: string | null;
  closed_at: string | null;
  /** The colleague's new duty, once approved */
  cover_roster_id: number | null;
  /** The requester's new duty of a swap, once approved */
  return_cover_roster_id: number | null;
  row_version: number;
}

export interface SwapIn {
  /** The duty to be worked by the colleague */
  roster_id: number;
  /** The colleague (same staff category): GET /self/roster/swap-options */
  covering_employee_id: number;
  /** For a swap: the colleague's duty the requester works in return; omit for a cover */
  return_roster_id?: number | null;
  reason: string;
}

export interface SwapNoteIn {
  note?: string | null;
}

export interface SwapRejectIn {
  /** Why (the two colleagues see it) */
  note: string;
}

