/** Roster entries for a date range (planner grid, a week by default) — GET /api/v1/rosters (who may call: holders of roster.manage.all or roster.manage.nursing or roster.manage.support or roster.view.all). */
export function listEntriesRosters(query?: { date_from?: string | null; date_to?: string | null; ward_id?: number | null; department_id?: number | null; employee_id?: number | null; staff_category?: "Clinical" | "Nursing" | "Administrative" | "Technical" | "SupportZeroInterface" | "Visiting" | null; include_cancelled?: boolean }): Promise<RosterRangeOut> {
  return api<RosterRangeOut>("GET", withQuery(`/rosters`, query), undefined);
}

/** Staff I may roster, with default shift and approved leave in the range — GET /api/v1/rosters/staff (who may call: holders of roster.manage.all or roster.manage.nursing or roster.manage.support). */
export function staffRosters(query?: { date_from?: string | null; date_to?: string | null; staff_category?: "Clinical" | "Nursing" | "Administrative" | "Technical" | "SupportZeroInterface" | "Visiting" | null; department_id?: number | null; q?: string | null }): Promise<RosterPlannerOut> {
  return api<RosterPlannerOut>("GET", withQuery(`/rosters/staff`, query), undefined);
}

/** Roster one or many duties (all or nothing) — POST /api/v1/rosters (who may call: holders of roster.manage.all or roster.manage.nursing or roster.manage.support). */
export function createEntries(body: EntriesIn): Promise<RosterEntryOut[]> {
  return api<RosterEntryOut[]>("POST", `/rosters`, body, { idempotent: true });
}

/** Change a duty (shift, date, place, beds, on-call, notes) — PATCH /api/v1/rosters/{roster_id} (who may call: holders of roster.manage.all or roster.manage.nursing or roster.manage.support). */
export function updateEntryRosters(roster_id: number, body: EntryPatch): Promise<RosterEntryOut> {
  return api<RosterEntryOut>("PATCH", `/rosters/${roster_id}`, body);
}

/** Cancel a duty (reason kept; never deleted) — POST /api/v1/rosters/{roster_id}/cancel (who may call: holders of roster.manage.all or roster.manage.nursing or roster.manage.support). */
export function cancelEntry(roster_id: number, body: RosterReasonIn): Promise<RosterEntryOut> {
  return api<RosterEntryOut>("POST", `/rosters/${roster_id}/cancel`, body);
}

/** Repeat a period (e.g. last week) from a later date — POST /api/v1/rosters/copy (who may call: holders of roster.manage.all or roster.manage.nursing or roster.manage.support). */
export function copyPeriod(body: CopyIn): Promise<RosterCopyOut> {
  return api<RosterCopyOut>("POST", `/rosters/copy`, body, { idempotent: true });
}

/** Week check: rest days per person, staff per day and shift — GET /api/v1/rosters/week (who may call: holders of roster.manage.all or roster.manage.nursing or roster.manage.support or roster.view.all). */
export function weekCheck(query?: { week_of?: string | null; ward_id?: number | null; department_id?: number | null; staff_category?: "Clinical" | "Nursing" | "Administrative" | "Technical" | "SupportZeroInterface" | "Visiting" | null }): Promise<RosterWeekOut> {
  return api<RosterWeekOut>("GET", withQuery(`/rosters/week`, query), undefined);
}

/** Duty swaps of the staff I roster (open ones by default) — GET /api/v1/rosters/swaps (who may call: holders of roster.manage.all or roster.manage.nursing or roster.manage.support). */
export function managerSwaps(query?: { status?: "Requested" | "Accepted" | "Approved" | "Declined" | "Rejected" | "Cancelled" | "Expired" | null }): Promise<DutySwapOut[]> {
  return api<DutySwapOut[]>("GET", withQuery(`/rosters/swaps`, query), undefined);
}

/** Record a swap agreed on the ward (staff without a login) — POST /api/v1/rosters/swaps (who may call: holders of roster.manage.all or roster.manage.nursing or roster.manage.support). */
export function recordSwap(body: SwapIn): Promise<DutySwapOut> {
  return api<DutySwapOut>("POST", `/rosters/swaps`, body, { idempotent: true });
}

/** Approve a duty swap — POST /api/v1/rosters/swaps/{swap_id}/approve (who may call: holders of roster.manage.all or roster.manage.nursing or roster.manage.support). */
export function approveSwap(swap_id: number, body: SwapNoteIn): Promise<DutySwapOut> {
  return api<DutySwapOut>("POST", `/rosters/swaps/${swap_id}/approve`, body);
}

/** Reject a duty swap — POST /api/v1/rosters/swaps/{swap_id}/reject (who may call: holders of roster.manage.all or roster.manage.nursing or roster.manage.support). */
export function rejectSwap(swap_id: number, body: SwapRejectIn): Promise<DutySwapOut> {
  return api<DutySwapOut>("POST", `/rosters/swaps/${swap_id}/reject`, body, { idempotent: true });
}

/** Roll-call sheet: who is rostered today and who has arrived — GET /api/v1/rosters/roll-call (who may call: holders of attendance.roll_call). */
export function rollCallSheet(query?: { roster_date?: string | null; shift_pattern_id?: number | null; ward_id?: number | null }): Promise<RollCallSheetOut> {
  return api<RollCallSheetOut>("GET", withQuery(`/rosters/roll-call`, query), undefined);
}

/** Mark rostered staff present (no badge station) — POST /api/v1/rosters/roll-call (who may call: holders of attendance.roll_call). */
export function takeRollCall(body: RollCallIn): Promise<RollCallOut> {
  return api<RollCallOut>("POST", `/rosters/roll-call`, body, { idempotent: true });
}
